#pragma once
// Scalar native stages: full-width IPv6 interval compiler (ATLAS), exact FIDX
// version 2 image builder (PACK) and packed image lookup kernel (TRACE).
// One translation unit, baseline x86-64, unsigned __int128 arithmetic only.
#include <algorithm>
#include <cstdint>
#include <cstring>
#include <map>
#include <stdexcept>
#include <string>
#include <vector>

using Key = unsigned __int128;
using u8 = uint8_t;
using u16 = uint16_t;
using u32 = uint32_t;
using u64 = uint64_t;

inline const Key DOMAIN_END = (Key)1 << 127;   // 2^127, only used shifted
inline const int KEY_WIDTH[3] = {16, 8, 4};

inline Key domain_size() {
    // 2^128 does not fit; callers use "open ended" flags instead.
    return (Key)0 - (Key)1;
}

inline std::string hexkey(Key x) {
    static const char* digits = "0123456789abcdef";
    std::string s(32, '0');
    for (int i = 31; i >= 0; --i) {
        s[i] = digits[(unsigned)(x & 15)];
        x >>= 4;
    }
    return s;
}

inline int hexdigit(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

inline Key key(const std::string& s) {
    if (s.empty() || s.size() > 32) throw std::runtime_error("key width");
    Key value = 0;
    for (char c : s) {
        int d = hexdigit(c);
        if (d < 0) throw std::runtime_error("key digit");
        value = (value << 4) | (Key)d;
    }
    return value;
}

inline std::vector<u8> unhex(const std::string& s) {
    if (s.size() % 2) throw std::runtime_error("hex length");
    std::vector<u8> out(s.size() / 2);
    for (size_t i = 0; i < out.size(); ++i) {
        int hi = hexdigit(s[2 * i]), lo = hexdigit(s[2 * i + 1]);
        if (hi < 0 || lo < 0) throw std::runtime_error("hex digit");
        out[i] = (u8)((hi << 4) | lo);
    }
    return out;
}

inline void put_u16(std::vector<u8>& b, size_t off, u16 v) {
    b[off] = (u8)(v & 0xff);
    b[off + 1] = (u8)((v >> 8) & 0xff);
}

inline void put_u32(std::vector<u8>& b, size_t off, u32 v) {
    b[off] = (u8)(v & 0xff);
    b[off + 1] = (u8)((v >> 8) & 0xff);
    b[off + 2] = (u8)((v >> 16) & 0xff);
    b[off + 3] = (u8)((v >> 24) & 0xff);
}

inline u32 get_u32(const u8* p) {
    return (u32)p[0] | ((u32)p[1] << 8) | ((u32)p[2] << 16) | ((u32)p[3] << 24);
}

inline u16 get_u16(const u8* p) {
    return (u16)((u16)p[0] | ((u16)p[1] << 8));
}

inline void put_key(std::vector<u8>& b, size_t off, Key value, int mode) {
    int width = KEY_WIDTH[mode];
    for (int i = 0; i < width; ++i) b[off + i] = (u8)((value >> (8 * i)) & 0xff);
}

inline Key get_key(const u8* p, int mode) {
    int width = KEY_WIDTH[mode];
    Key value = 0;
    for (int i = width - 1; i >= 0; --i) value = (value << 8) | (Key)p[i];
    return value;
}

// ---------------------------------------------------------------- ATLAS ----

struct Route {
    Key start;
    int length;
    int hop;
};

struct AtlasEvent {
    Key pos;
    int kind;      // 0 = route ends here, 1 = route starts here
    int length;
    int hop;
};

inline bool atlas_less(const AtlasEvent& a, const AtlasEvent& b) {
    if (a.pos != b.pos) return a.pos < b.pos;
    if (a.kind != b.kind) return a.kind < b.kind;   // ends leave before starts
    return a.length < b.length;                     // laminar: shorter outside
}

// Unique maximal forwarding runs of one RIB version: (run start, hop), hop -1
// for null, starting at zero, adjacent equal hops coalesced.
inline std::vector<std::pair<Key, int>> atlas_runs(const std::vector<Route>& fib) {
    std::vector<AtlasEvent> events;
    events.reserve(fib.size() * 2);
    for (const Route& r : fib) {
        events.push_back({r.start, 1, r.length, r.hop});
        if (r.length > 0) {
            Key size = (Key)1 << (128 - r.length);
            Key end = r.start + size;
            if (end > r.start) events.push_back({end, 0, r.length, r.hop});
        }
    }
    std::sort(events.begin(), events.end(), atlas_less);
    std::vector<std::pair<Key, int>> runs;
    std::vector<int> stack;
    Key cursor = 0;
    int current = -1;
    size_t i = 0;
    while (i < events.size()) {
        Key pos = events[i].pos;
        if (pos > cursor) {
            if (runs.empty() || runs.back().second != current) runs.push_back({cursor, current});
            cursor = pos;
        }
        int closes = 0;
        std::vector<int> opens;
        while (i < events.size() && events[i].pos == pos) {
            if (events[i].kind == 0) ++closes;
            else opens.push_back(events[i].hop);
            ++i;
        }
        for (int t = 0; t < closes; ++t)
            if (!stack.empty()) stack.pop_back();
        for (int hop : opens) stack.push_back(hop);
        current = stack.empty() ? -1 : stack.back();
    }
    if (runs.empty() || runs.back().second != current) runs.push_back({cursor, current});
    if (runs.empty()) runs.push_back({(Key)0, -1});
    return runs;
}

// ----------------------------------------------------------------- image ---

struct ImgNode {
    int kind;              // 0 internal, 1 leaf
    int mode;
    int cached;
    int lo;
    int span;
    int count;             // children for internal, span for leaf
    u32 allocated;
    u32 offset;
    Key base;
    std::vector<u32> children;   // byte offsets, internal only
    std::vector<Key> keys;       // absolute keys
};

struct Img {
    std::vector<u8> bytes;
    u32 runs = 0, nodes = 0, hop_offset = 0, total = 0;
    std::vector<ImgNode> records;         // record order
    std::map<u32, size_t> index;          // byte offset -> record slot
    std::vector<int> hops;                // -1 for null

    int lookup(Key address, std::vector<u32>& path) const {
        size_t slot = index.at(64);
        int run = 0;
        for (;;) {
            const ImgNode& node = records[slot];
            path.push_back(node.offset);
            const std::vector<Key>& keys = node.keys;
            size_t at = (size_t)(std::upper_bound(keys.begin(), keys.end(), address) - keys.begin());
            if (node.kind == 1) {
                if (at == 0) throw std::runtime_error("leaf predecessor");
                run = node.lo + (int)at - 1;
                return run;
            }
            if (at > node.children.size()) at = node.children.size();
            slot = index.at(node.children[at]);
        }
    }
};

inline u32 align64(u32 value) { return (value + 63u) & ~63u; }

// Layout row as supplied by PACK.
struct Layout {
    int lo, span, mode, cached;
    std::vector<int> children;
};

inline u32 node_used(const ImgNode& n) {
    if (n.kind == 1) return 32u + (u32)n.span * (u32)KEY_WIDTH[n.mode];
    u32 b = (u32)n.children.size();
    return 32u + 4u * b + (b - 1u) * (u32)KEY_WIDTH[n.mode];
}

inline Img decode_image(const std::vector<u8>& raw) {
    Img img;
    if (raw.size() < 128 || raw.size() % 64) throw std::runtime_error("image size");
    if (std::memcmp(raw.data(), "FIDX", 4) != 0 || raw[4] != 2)
        throw std::runtime_error("image magic");
    img.bytes = raw;
    img.runs = get_u32(raw.data() + 8);
    img.nodes = get_u32(raw.data() + 12);
    img.hop_offset = get_u32(raw.data() + 16);
    img.total = get_u32(raw.data() + 20);
    if (img.total != raw.size()) throw std::runtime_error("image total");
    if (img.runs < 1 || img.nodes < 1) throw std::runtime_error("image counts");
    for (u32 n = 0; n < img.nodes; ++n) {
        u32 off = (u32)(64 + (size_t)n * 0);   // replaced below by walk
        (void)off;
        break;
    }
    u32 offset = 64;
    for (u32 n = 0; n < img.nodes; ++n) {
        if (offset + 32 > img.hop_offset) throw std::runtime_error("truncated node");
        ImgNode node;
        const u8* p = raw.data() + offset;
        node.kind = p[0];
        node.mode = p[1];
        node.cached = p[2];
        if (p[3] != 0) throw std::runtime_error("node reserved");
        node.lo = get_u16(p + 4);
        node.span = get_u16(p + 6);
        node.count = get_u16(p + 8);
        node.allocated = get_u32(p + 12);
        node.offset = offset;
        node.base = get_key(p + 16, 0);
        if (node.mode < 0 || node.mode > 2) throw std::runtime_error("node mode");
        size_t cursor = (size_t)offset + 32;
        if (node.kind == 0) {
            int b = node.count;
            if (b < 2 || b > 9) throw std::runtime_error("child count");
            node.children.resize(b);
            for (int c = 0; c < b; ++c) {
                node.children[c] = get_u32(raw.data() + cursor);
                cursor += 4;
            }
            for (int c = 0; c < b - 1; ++c) {
                node.keys.push_back(node.base + get_key(raw.data() + cursor, node.mode));
                cursor += KEY_WIDTH[node.mode];
            }
        } else if (node.kind == 1) {
            int s = node.span;
            if (s < 1 || s > 8 || node.count != s) throw std::runtime_error("leaf span");
            for (int t = 0; t < s; ++t) {
                node.keys.push_back(node.base + get_key(raw.data() + cursor, node.mode));
                cursor += KEY_WIDTH[node.mode];
            }
        } else {
            throw std::runtime_error("node kind");
        }
        img.index[offset] = img.records.size();
        img.records.push_back(std::move(node));
        offset += img.records.back().allocated;
    }
    if (offset != img.hop_offset) throw std::runtime_error("node walk");
    img.hops.resize(img.runs);
    for (u32 r = 0; r < img.runs; ++r) {
